import{_ as e,o as r,c as o,al as t}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"Заводське калібрування IMU/компаса","description":"","frontmatter":{},"headers":[],"relativePath":"uk/advanced_config/imu_factory_calibration.md","filePath":"uk/advanced_config/imu_factory_calibration.md"}'),i={name:"uk/advanced_config/imu_factory_calibration.md"};function c(n,a,l,_,d,s){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="заводське-калібрування-imu-компаса" tabindex="-1">Заводське калібрування IMU/компаса <a class="header-anchor" href="#заводське-калібрування-imu-компаса" aria-label="Permalink to &quot;Заводське калібрування IMU/компаса&quot;">​</a></h1><p>Виробники PX4 OEM можуть виконувати IMU і компасувати завод для збереження значень для акселерометра, калібрування гіроскопа та магнітометра у постійне сховище (зазвичай ЕЗПМ). Це забезпечує можливість завжди скидати конфігурації та налаштування транспортного засобу до безпечного стану для польоту.</p><p>This procedure will write the following parameters to <code>/fs/mtd_caldata</code>: <a href="./../advanced_config/parameter_reference#CAL_ACC0_ID">CAL_ACC*</a>, <a href="./../advanced_config/parameter_reference#CAL_GYRO0_ID">CAL_GYRO*</a>, <a href="./../advanced_config/parameter_reference#CAL_MAG0_ID">CAL_MAG*</a>. Ці дані будуть використані, коли параметри будуть встановлені (або скинуті) до їхніх значень за замовчуванням.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This feature relies on the FMU having a dedicated EEPROM chip or an accompanying IMU PCBA that has sufficient space for the data. PX4 will store the data to <code>/fs/mtd_caldata</code>, creating the file if necessary.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Ці значення не можуть бути збережені в <a href="./../dev_airframes/adding_a_new_frame">конфігурації кадрів</a> оскільки вони відрізняються від пристрою в пристрої (конфігурація рамки визначає набір параметрів, які застосовуються на всіх автомобілях того ж типу, такі, як увімкнені датчики, <a href="./../config/flight_controller_orientation">обертання автопілота</a> і настроювання PID).</p></div><h2 id="виконання-заводського-калібрування" tabindex="-1">Виконання заводського калібрування <a class="header-anchor" href="#виконання-заводського-калібрування" aria-label="Permalink to &quot;Виконання заводського калібрування&quot;">​</a></h2><ol><li>Встановіть параметр <a href="./../advanced_config/parameter_reference#SYS_FAC_CAL_MODE">SYS_FAC_CAL_MODE</a> на 1.</li><li>Виконайте всі калібрування IMU: <a href="./../config/accelerometer#performing-the-calibration">акселерометр</a>, <a href="./../config/gyroscope#performing-the-calibration">гіроскоп</a> і <a href="./../config/compass#performing-the-calibration">магнітометр</a>.</li><li>Перезапустіть транспортний засіб. This will write all <code>CAL_ACC*</code>, <code>CAL_GYRO*</code> and <code>CAL_MAG*</code> parameters into <code>/fs/mtd_caldata</code>.</li><li>Знову встановіть параметр <code>SYS_FAC_CAL_MODE</code> на 0 (за замовчуванням).</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Якщо ви хочете провести заводську калібрування лише акселерометра та гіроскопа, ви можете встановити <a href="./../advanced_config/parameter_reference#SYS_FAC_CAL_MODE">SYS_FAC_CAL_MODE</a> на 2, у цьому випадку магнітометр виключається.</p></div><p>Подальші корекції користувача будуть враховані як зазвичай (дані заводського калібрування використовуються лише для значень за замовчуванням параметрів).</p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/sensors_px4.html" target="_blank" rel="noreferrer">Посібник користувача з QGroundControl &gt; Датчики</a></li><li><a href="./../advanced_config/oem">OEM/Factory Configuration</a></li></ul>',11)])])}const h=e(i,[["render",c]]);export{p as __pageData,h as default};
